/**
 * Public route group — mounted at `/public`, NO authentication.
 * Access is gated entirely by the unguessable UUID `public_token` in
 * the URL (capability-style), and the routes never exist for tokens
 * that were not generated by a real send.
 *
 * The customer sees an ESTIMATE (the document we emailed) even though
 * the underlying record is an ORDER. Confirming it moves the order
 * `sent → awaiting_payment` and stamps `confirmed_at`. After that the
 * SAME url keeps working as a live order summary — status tracker,
 * balance and e-Transfer details — which is why no status-update emails
 * are sent to customers.
 *
 * Endpoints:
 *   GET  /estimate/:token          customer-facing order/estimate view data
 *   POST /estimate/:token/view     record the customer's first page open
 *   POST /estimate/:token/confirm  one-shot confirm (rate-limited)
 *   POST /estimate/:token/cancel-request   ask to cancel the confirmation
 *   POST /estimate/:token/cancel-withdraw  take that request back
 *   POST /estimate/:token/edit-request     ask for a change before confirming
 *   GET  /appointment/:token       visit proposal (estimate or install)
 *   POST /appointment/:token/confirm  confirm the proposed window
 *   POST /appointment/:token/request  ask for a different time (+note)
 *
 * Every endpoint above sits behind the rate limiter and then the
 * MAINTENANCE GATE: when staff flip `company_settings.maintenance_mode`
 * on, this whole group answers 503 with the configured message and no
 * order or appointment record is touched. Only the customer surfaces
 * close — the authenticated `/api/*` staff app keeps working.
 *
 * The confirm endpoint validates status='sent' (409 once it has moved
 * on), stamps confirmed_at, and fires an internal notification email —
 * notification failure is logged but never blocks the customer's
 * confirmation. Both endpoints apply the defensive expiry check so a
 * stale 'sent' order reads as expired even if the daily cron hasn't
 * run yet.
 *
 * NOTE (task: reversible confirmations): the customer can confirm but
 * can NEVER reverse — undoing a confirmation is a user-only action on
 * the authenticated `/api/orders/:id/unconfirm` route. The most a
 * customer can do is REQUEST cancellation here; the request is a flag
 * on the order (`cancel_requested_at`) and changes no status by itself.
 * Staff answer it on `/api/orders/:id/cancel-request/resolve`.
 *
 * NOTE (task: customer edit requests): the same one-way shape applies
 * BEFORE a confirmation exists. `POST /estimate/:token/edit-request`
 * appends a free-text message to `order_edit_requests` and changes no
 * status, no line item and no money — a customer never mutates the
 * order itself (AI_GUIDELINES rule 1). Staff read the requests on the
 * order page and close them on
 * `/api/orders/:id/edit-requests/:requestId/resolve`.
 */

import { Hono } from 'hono';
import type { SupabaseClient } from '@supabase/supabase-js';
import { createSupabaseAdmin } from '../lib/supabase';
import publicCustomerRoutes from './publicCustomer';
import { rateLimit } from '../middleware/rateLimit';
import { displayName } from '../lib/customerName';
import { recordNotification } from '../lib/notifications';
import { buildPublicQuote, toPublicLines } from '../lib/publicQuote';
import { readPublicRevision, resolveServedQuote } from '../lib/publicRevision';
import { checkLatestRevision } from '../lib/orderRevisions';
import { diffQuotes } from '../lib/quoteDiff';
import {
  sendEmail,
  buildConfirmationNoticeHtml,
  buildInstallationNoticeHtml,
  buildAppointmentNoticeHtml,
  buildCancellationNoticeHtml,
} from '../lib/email';
import type { Env } from '../index';

const app = new Hono<{ Bindings: Env }>();

/** UUID v4 shape — reject junk tokens before touching the DB. */
const TOKEN_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Requests per IP per minute across every `/public/*` route. Raised from
 * 5 to 20 for the customer link (2026-10-22): browsing list → estimate →
 * list → estimate is already six requests. Tokens are random UUIDs, so
 * this is an abuse brake, not what keeps an estimate private.
 */
export const PUBLIC_RATE_LIMIT = 20;

/** Rate limit everything under /public (`PUBLIC_RATE_LIMIT` requests/min/IP). */
app.use('*', rateLimit(PUBLIC_RATE_LIMIT, 60_000));

/** Served when maintenance mode is on and no message is configured. */
const MAINTENANCE_FALLBACK =
  'We are briefly offline for maintenance. Please check back shortly.';

/**
 * Maintenance gate — closes the CUSTOMER surfaces on a staff toggle.
 *
 * Reads `company_settings.maintenance_mode` (migration 40) before ANY
 * public handler runs and, while it is on, answers every route in this
 * group with `503 { error, maintenance: true, message }`. `maintenance`
 * is the flag the customer pages branch on to render a maintenance card
 * instead of their "not found" state; `message` is the staff wording,
 * or `MAINTENANCE_FALLBACK` when none is configured.
 *
 * Deliberately scoped to `/public/*` only: `/api/*` stays open so staff
 * can keep working — being able to fix things while customers are held
 * off is the entire point of the switch.
 *
 * Registered AFTER the rate limiter so a flood still costs one in-memory
 * check rather than a database read, and it is the FIRST thing that
 * touches the DB — no order or appointment row is read, written, or
 * status-changed while the shop is closed. A failed settings read is
 * treated as "open": a transient Supabase error must not silently take
 * the customer-facing site down.
 */
app.use('*', async (c, next) => {
  const sb = createSupabaseAdmin(c.env);
  const { data } = await sb
    .from('company_settings')
    .select('maintenance_mode, maintenance_message')
    .eq('id', 1)
    .single();

  if (!data?.maintenance_mode) return next();

  const message = (data.maintenance_message as string | null)?.trim() || MAINTENANCE_FALLBACK;
  return c.json({ error: message, maintenance: true, message }, 503);
});

// Customer link (`/public/customer/:token`) — after both gates above.
app.route('/customer', publicCustomerRoutes);

/**
 * Best-effort activity-trail entry on an order, always attributed to the
 * customer — this module is the token'd public surface, so nothing here
 * is ever a staff action.
 *
 * Mirrors the same-named helpers in `orders.ts` and `appointments.ts`
 * (route modules deliberately do not import from one another). Errors
 * are swallowed: a customer's confirmation must never fail because the
 * diagnostic log behind it did.
 */
async function logOrderEvent(
  sb: SupabaseClient,
  orderId: string,
  message: string
): Promise<void> {
  try {
    await sb.from('order_logs').insert({ order_id: orderId, message, source: 'customer' });
  } catch {
    // Logging is diagnostic only — never block the customer's action.
  }
}

/**
 * Loads an order (+items/customer/payments) by public token, or null.
 *
 * The `payments(amount, paid_on)` embed lets the Worker compute
 * paid-to-date and the outstanding balance server-side AND render the
 * customer's own receipt history. Only those two columns are selected:
 * the row `id`, the internal `note`, and `receipt_sent_at` are staff
 * data and never reach the public payload (see the sanitizer below).
 *
 * The `order_edit_requests` embed is the customer's OWN messages read
 * back to them, so every column of it is already theirs — the row is
 * whole-cloth customer input plus the staff resolution stamp. It rides
 * on this query rather than a second round-trip because every caller
 * that needs it already loads the order.
 */
async function loadByToken(sb: SupabaseClient, token: string) {
  const { data } = await sb
    .from('orders')
    // One literal, deliberately long: supabase-js parses the select at
    // the TYPE level, and a concatenated string widens to `string`,
    // which collapses the whole row type to a parse error.
    .select('*, line_items(*), customer:customers(*), payments(amount, paid_on), order_edit_requests(id, message, created_at, resolved_at)')
    .eq('public_token', token)
    .order('position', { referencedTable: 'line_items' })
    .maybeSingle();
  return data;
}

/**
 * Sums a payments embed into paid-to-date. Mirrors `sumPayments` in
 * `routes/orders.ts`; kept local because the public payload deliberately
 * shares no code path (and no shape) with the authenticated detail
 * response.
 */
function sumPayments(payments: Array<{ amount: number | string }> | null | undefined): number {
  return (payments ?? []).reduce((acc, p) => acc + Number(p.amount), 0);
}

/**
 * The standard up-front deposit: half the order total, rounded to the
 * cent. This is the SAME 50% rule the incoming e-Transfer matcher uses
 * to recognise a deposit payment (`lib/etransferMatch.ts`) — the two
 * must agree, otherwise the figure quoted to the customer would not be
 * auto-matched when it arrives. Computed here rather than in the browser
 * so no money figure originates client-side (AI_GUIDELINES rule 1).
 */
function depositDue(total: number | string): number {
  return Math.round((Number(total) / 2) * 100) / 100;
}

/** One receipt line on the customer's payment history. */
interface PublicPayment {
  amount: number;
  paid_on: string;
}

/**
 * Reduces the payments embed to the receipt history the customer sees:
 * amount + date only, oldest-first so the list reads as a running
 * record. Supabase does not guarantee embed ordering, so sort here
 * rather than relying on insertion order.
 */
function publicPayments(
  payments: Array<{ amount: number | string; paid_on: string }> | null | undefined
): PublicPayment[] {
  return (payments ?? [])
    .map((p) => ({ amount: Number(p.amount), paid_on: p.paid_on }))
    .sort((a, b) => a.paid_on.localeCompare(b.paid_on));
}

/** Statuses in which a confirmation still exists to be cancelled. */
const CANCELLABLE_STATUS = 'awaiting_payment';

/**
 * The only status in which an edit request is accepted.
 *
 * Edit requests belong to the pre-confirmation conversation: the button
 * that raises one lives in the customer's fixed action bar, which the
 * page renders only while the estimate is unconfirmed. Once the order
 * moves on, the cancellation flow is the remaining lever and this route
 * answers 409 rather than filing a message nobody expects.
 */
const EDIT_REQUEST_STATUS = 'sent';

/**
 * Hard cap on UNRESOLVED edit requests per order.
 *
 * The group's 5-req/min/IP limiter stops a flood; this stops a slow
 * drip from burying the staff order page under a wall of open messages.
 * Counted rather than enforced by a constraint because "open" is a
 * partial predicate that changes as staff work through the list — a
 * customer who is answered can always ask again.
 */
const MAX_OPEN_EDIT_REQUESTS = 5;

/** Longest customer message stored; anything beyond is truncated, not rejected. */
const EDIT_REQUEST_MAX_CHARS = 1000;

/** One change request as the customer's own page renders it. */
interface PublicEditRequest {
  id: string;
  message: string;
  created_at: string;
  /** Set once staff amended the order and closed the request out. */
  resolved_at: string | null;
}

/**
 * Normalises the `order_edit_requests` embed for the public payload.
 *
 * Sorted oldest-first so the list reads as a conversation in the order
 * it happened; Supabase does not guarantee embed ordering, so the sort
 * belongs here rather than being assumed from insertion order. Nothing
 * is stripped — every column is either the customer's own text or the
 * resolution stamp they are entitled to see.
 */
function publicEditRequests(
  rows: Array<Record<string, unknown>> | null | undefined
): PublicEditRequest[] {
  return (rows ?? [])
    .map((r) => ({
      id: String(r.id),
      message: String(r.message ?? ''),
      created_at: String(r.created_at),
      resolved_at: (r.resolved_at as string | null) ?? null,
    }))
    .sort((a, b) => a.created_at.localeCompare(b.created_at));
}

/**
 * Internal notice when a customer opens or withdraws a cancellation
 * request. Best effort in the established `/public` style: staff also
 * see an open request as a red banner on the order page, so a failed
 * send is logged and never surfaces to the customer.
 */
async function notifyCancellationRequest(
  env: Env,
  order: Record<string, any>,
  withdrawn: boolean,
  note?: string
): Promise<void> {
  try {
    const sb = createSupabaseAdmin(env);
    const { data: company } = await sb
      .from('company_settings')
      .select('email, company_name')
      .eq('id', 1)
      .single();
    if (!company?.email) return;
    const customerName = displayName(order.customer);
    await sendEmail(env, {
      to: company.email,
      subject: withdrawn
        ? `↩️ Cancellation request withdrawn — ${order.order_number}`
        : `⚠️ Cancellation requested — ${order.order_number}`,
      html: buildCancellationNoticeHtml({
        orderNumber: order.order_number,
        customerName,
        total: Number(order.total),
        withdrawn,
        note,
      }),
    });
  } catch (e) {
    console.error('Cancellation notification failed:', e);
  }
}

/** Defensive expiry: flips stale 'sent' orders to expired in the DB. */
async function effectiveStatus(
  sb: SupabaseClient,
  order: { id: string; status: string; expiry_date: string }
): Promise<string> {
  const today = new Date().toISOString().slice(0, 10);
  if (order.status === 'sent' && order.expiry_date < today) {
    await sb.from('orders').update({ status: 'expired' }).eq('id', order.id);
    return 'expired';
  }
  return order.status;
}

/** Public estimate view — everything the CustomerView page renders. */
app.get('/estimate/:token', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Estimate not found' }, 404);

  const sb = createSupabaseAdmin(c.env);
  const order = await loadByToken(sb, token);
  if (!order) return c.json({ error: 'Estimate not found' }, 404);
  const status = await effectiveStatus(sb, order);

  const { data: company } = await sb
    .from('company_settings')
    .select(
      'company_name, logo_url, email, phone, address, hst_number, ' +
      'etransfer_email, etransfer_instructions'
    )
    .eq('id', 1)
    .single();

  // Money is computed here, never accepted from or trusted to the
  // client (AI_GUIDELINES rule 1). The aggregates and the amount/date
  // of each receipt cross the wire; staff-only payment columns do not.
  const amountPaid = sumPayments(order.payments);

  // The customer-visible quote: the latest SENT revision while the estimate
  // waits on the customer, else the live order (lib/publicRevision.ts). An
  // unreadable history is a 500, never a silent fall back to unsent edits.
  const resolved = await resolveServedQuote(sb, order, status);
  if ('error' in resolved) {
    return c.json({ error: 'Something went wrong. Please try again.' }, 500);
  }
  const { quote, ...revisionFields } = resolved.served;

  // Sanitized payload: only what the customer page needs.
  return c.json({
    data: {
      status,
      order_number: order.order_number,
      ...quote,
      ...revisionFields,
      amount_paid: amountPaid,
      // Both follow the SERVED total, so the page's money adds up to the
      // figures it is showing.
      balance: quote.total - amountPaid,
      // Quoted to the customer while the order sits in awaiting_payment;
      // always served so the page never has to derive money itself.
      deposit_due: depositDue(quote.total),
      payments: publicPayments(order.payments),
      confirmed_at: order.confirmed_at,
      cancel_requested_at: order.cancel_requested_at ?? null,
      // The customer's own change requests, read back so the page can
      // show that a message landed and whether staff have closed it.
      edit_requests: publicEditRequests(order.order_edit_requests),
      customer: {
        first_name: order.customer?.first_name ?? '',
        last_name: order.customer?.last_name ?? '',
        shipping_address_line1: order.customer?.shipping_address_line1 ?? '',
        shipping_address_line2: order.customer?.shipping_address_line2 ?? '',
        shipping_city: order.customer?.shipping_city ?? '',
        shipping_province: order.customer?.shipping_province ?? '',
        shipping_postal_code: order.customer?.shipping_postal_code ?? '',
      },
      company,
      // Hidden items are already dropped and `uid` is staff/diff-only, so it
      // is stripped before the lines leave the Worker.
      line_items: toPublicLines(quote.line_items),
    },
  });
});

/**
 * One earlier revision of the estimate, read-only — the customer page's
 * "previous versions" view. Served at any status (history stays
 * readable after confirmation) and only for the order the token opens.
 * Lines pass through `toPublicLines`; the revision row's id, kind and
 * staff copy never leave the Worker.
 */
app.get('/estimate/:token/revisions/:rev', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Estimate not found' }, 404);

  const sb = createSupabaseAdmin(c.env);
  const order = await loadByToken(sb, token);
  if (!order) return c.json({ error: 'Estimate not found' }, 404);

  const read = await readPublicRevision(sb, order.id, c.req.param('rev'));
  if ('error' in read) return c.json({ error: 'Something went wrong. Please try again.' }, 500);
  if (!read.row) return c.json({ error: 'Revision not found' }, 404);

  const { rev_no, sent_at, snapshot } = read.row;
  return c.json({
    data: {
      rev_no,
      sent_at,
      ...snapshot,
      line_items: toPublicLines(snapshot.line_items),
      read_only: true,
    },
  });
});

/**
 * Records that the customer opened their page — the trail's only
 * evidence that the emailed link was actually read.
 *
 * Fired once by `CustomerView` on mount and never again: the browser
 * suppresses repeats per token, and `orders.customer_viewed_at` makes
 * the server refuse a second log regardless of what the client does.
 * Staff previews (`?preview=1`) never call this at all.
 *
 * Always answers 200 for a real token, even when nothing was written —
 * this is telemetry, and a customer's page must never surface an error
 * because a log failed. 404 only for a malformed or unknown token, with
 * the same wording as its neighbours so nothing leaks about which
 * tokens exist.
 */
app.post('/estimate/:token/view', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Estimate not found' }, 404);

  const sb = createSupabaseAdmin(c.env);
  const order = await loadByToken(sb, token);
  if (!order) return c.json({ error: 'Estimate not found' }, 404);

  // A draft was never sent to anyone, so there is no "customer opened
  // it" event to record — the page itself refuses to render one.
  if (order.status === 'draft') return c.json({ data: { ok: true } });
  if (order.customer_viewed_at) return c.json({ data: { ok: true } });

  await sb
    .from('orders')
    .update({ customer_viewed_at: new Date().toISOString() })
    .eq('id', order.id);
  await logOrderEvent(sb, order.id, 'Customer opened their order page.');

  return c.json({ data: { ok: true } });
});

/**
 * Customer confirm — succeeds exactly once, moving the order
 * sent → awaiting_payment.
 * 404 unknown token · 409 already confirmed · 410 expired · 400 draft.
 */
app.post('/estimate/:token/confirm', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Estimate not found' }, 404);

  const sb = createSupabaseAdmin(c.env);
  const order = await loadByToken(sb, token);
  if (!order) return c.json({ error: 'Estimate not found' }, 404);

  const status = await effectiveStatus(sb, order);
  if (status === 'expired') {
    return c.json({ error: 'This estimate has expired. Please contact us for a new quote.' }, 410);
  }
  if (status !== 'sent') {
    // Anything past 'sent' (awaiting_payment / in_progress / completed)
    // has already been confirmed.
    return c.json({ error: 'This estimate has already been confirmed.' }, 409);
  }

  // The customer accepts the revision their page shows — the latest one.
  // Unreadable history is a 500 so an acceptance is never recorded blind.
  const latestRead = await checkLatestRevision(sb, order.id);
  if ('error' in latestRead) {
    return c.json({ error: 'Something went wrong. Please try again.' }, 500);
  }
  const latest = latestRead.row;

  // Guard the transition at the DB level too: only a 'sent' row updates,
  // so two racing confirms produce exactly one winner.
  const { data: updated, error } = await sb
    .from('orders')
    .update({
      status: 'awaiting_payment',
      confirmed_at: new Date().toISOString(),
      accepted_revision_id: latest?.id ?? null,
    })
    .eq('id', order.id)
    .eq('status', 'sent')
    .select('id, total, order_number')
    .maybeSingle();
  if (error) return c.json({ error: error.message }, 500);
  if (!updated) return c.json({ error: 'This estimate has already been confirmed.' }, 409);

  await logOrderEvent(sb, order.id, 'Customer confirmed the estimate.');
  // Staff saved edits after the last send: the customer accepted the sent
  // revision, not those edits, and the trail has to say so.
  if (latest && diffQuotes(latest.snapshot, buildPublicQuote(order)).length > 0) {
    await logOrderEvent(
      sb,
      order.id,
      `Customer confirmed Rev ${latest.rev_no}; later unsent changes are not part of it.`
    );
  }
  await recordNotification(sb, {
    kind: 'order_confirmed',
    orderId: order.id,
    orderNumber: updated.order_number,
    customerName: displayName(order.customer),
  });

  // Internal notification — best effort, never blocks the customer.
  try {
    const { data: company } = await sb
      .from('company_settings')
      .select('email, company_name')
      .eq('id', 1)
      .single();
    if (company?.email) {
      await sendEmail(c.env, {
        to: company.email,
        subject: `✅ Estimate ${updated.order_number} confirmed`,
        html: buildConfirmationNoticeHtml({
          orderNumber: updated.order_number,
          customerName: displayName(order.customer),
          total: Number(updated.total),
        }),
      });
    }
  } catch (e) {
    console.error('Confirmation notification failed:', e);
  }

  return c.json({ data: { status: 'awaiting_payment', total: Number(updated.total) } });
});

/* ------------------------------------------------------------------ */
/* Cancellation requests (customer asks, staff answers)                */
/* ------------------------------------------------------------------ */

/**
 * Customer asks for their confirmation to be cancelled.
 *
 * This changes NO order status — it only raises `cancel_requested_at`,
 * which surfaces as a red banner on the staff order page. Undoing a
 * confirmation stays a user-only action.
 *
 * Accepted only while the order is `awaiting_payment` with zero
 * payments — precisely the window in which `/api/orders/:id/unconfirm`
 * would still succeed, so staff can never be handed a request they are
 * unable to grant. The status half of that rule is re-applied as a DB
 * guard on the UPDATE, so a payment landing mid-request cannot slip past
 * the read-then-write gap.
 *
 * 404 unknown token · 409 wrong status, payment already recorded, or a
 * request already open (which also makes a double tap idempotent and
 * stops duplicate staff notifications).
 */
app.post('/estimate/:token/cancel-request', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Estimate not found' }, 404);

  const body = (await c.req.json().catch(() => ({}))) as { note?: unknown };
  const note = typeof body.note === 'string' ? body.note.slice(0, 500) : '';

  const sb = createSupabaseAdmin(c.env);
  const order = await loadByToken(sb, token);
  if (!order) return c.json({ error: 'Estimate not found' }, 404);

  if (order.status !== CANCELLABLE_STATUS) {
    return c.json(
      { error: 'This order can no longer be cancelled online. Please contact us directly.' },
      409
    );
  }
  if (sumPayments(order.payments) > 0) {
    return c.json(
      { error: 'A payment has already been recorded. Please contact us directly.' },
      409
    );
  }
  if (order.cancel_requested_at) {
    return c.json({ error: 'We have already received your cancellation request.' }, 409);
  }

  const { data: updated, error } = await sb
    .from('orders')
    .update({ cancel_requested_at: new Date().toISOString(), cancel_request_note: note })
    .eq('id', order.id)
    .eq('status', CANCELLABLE_STATUS)
    .is('cancel_requested_at', null)
    .select('id')
    .maybeSingle();
  if (error) return c.json({ error: error.message }, 500);
  if (!updated) {
    return c.json({ error: 'We have already received your cancellation request.' }, 409);
  }

  // The customer's free-text note is deliberately NOT interpolated into
  // the trail message: staff already receive it in the notification
  // email and on the order's own `cancel_request_note`.
  await logOrderEvent(sb, order.id, 'Customer requested cancellation.');

  await notifyCancellationRequest(c.env, order, false, note);
  return c.json({ data: { cancel_requested: true } });
});

/**
 * Customer takes back a cancellation request they already opened.
 *
 * Clears the flag and the note so the staff banner disappears. Guarded
 * on the flag being set, so a stale tab cannot clear a request that
 * staff have already answered.
 *
 * 404 unknown token · 409 when no request is open.
 */
app.post('/estimate/:token/cancel-withdraw', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Estimate not found' }, 404);

  const sb = createSupabaseAdmin(c.env);
  const order = await loadByToken(sb, token);
  if (!order) return c.json({ error: 'Estimate not found' }, 404);
  if (!order.cancel_requested_at) {
    return c.json({ error: 'There is no cancellation request to withdraw.' }, 409);
  }

  const { data: updated, error } = await sb
    .from('orders')
    .update({ cancel_requested_at: null, cancel_request_note: '' })
    .eq('id', order.id)
    .not('cancel_requested_at', 'is', null)
    .select('id')
    .maybeSingle();
  if (error) return c.json({ error: error.message }, 500);
  if (!updated) {
    return c.json({ error: 'There is no cancellation request to withdraw.' }, 409);
  }

  await logOrderEvent(sb, order.id, 'Customer withdrew their cancellation request.');

  await notifyCancellationRequest(c.env, order, true);
  return c.json({ data: { cancel_requested: false } });
});

/* ------------------------------------------------------------------ */
/* Edit requests (customer asks for a change before confirming)        */
/* ------------------------------------------------------------------ */

/**
 * Customer asks for a change to their estimate.
 *
 * Appends one free-text message to `order_edit_requests` and does
 * NOTHING else: no status moves, no line item or money field is touched,
 * and Confirm stays available — the customer may still accept the
 * estimate as quoted while a question is outstanding. Staff read the
 * open requests on the order page and close each one there.
 *
 * Accepted only on a `sent` order, which is the window in which the
 * customer's action bar (and therefore the button) exists at all. The
 * status is re-read here rather than trusted from the page, so a stale
 * tab left open across a confirmation cannot file a request against an
 * order that has moved on.
 *
 * The open-request cap is counted immediately before the insert. Two
 * simultaneous submits could each see four and both write, landing six
 * open rows; that race is benign by design — the cap exists to stop a
 * wall of messages, not to be an invariant worth a trigger or a lock.
 *
 * 400 empty message · 404 unknown token · 409 wrong status or cap
 * reached.
 */
app.post('/estimate/:token/edit-request', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Estimate not found' }, 404);

  const body = (await c.req.json().catch(() => ({}))) as { message?: unknown };
  // Truncated, not rejected: a customer who pastes a long note should
  // have it filed, not bounced for a limit they were never shown.
  const message =
    typeof body.message === 'string' ? body.message.trim().slice(0, EDIT_REQUEST_MAX_CHARS) : '';
  if (!message) return c.json({ error: 'Please tell us what you would like changed.' }, 400);

  const sb = createSupabaseAdmin(c.env);
  const order = await loadByToken(sb, token);
  if (!order) return c.json({ error: 'Estimate not found' }, 404);

  // Defensive expiry first: a lapsed estimate must read as expired here
  // exactly as it does on the page, rather than quietly accepting a
  // request against something the customer can no longer confirm.
  const status = await effectiveStatus(sb, order);
  if (status !== EDIT_REQUEST_STATUS) {
    return c.json(
      { error: 'This estimate can no longer be changed online. Please contact us directly.' },
      409
    );
  }

  const { count, error: countError } = await sb
    .from('order_edit_requests')
    .select('id', { count: 'exact', head: true })
    .eq('order_id', order.id)
    .is('resolved_at', null);
  if (countError) return c.json({ error: countError.message }, 500);
  if ((count ?? 0) >= MAX_OPEN_EDIT_REQUESTS) {
    return c.json(
      { error: 'We already have your change requests. Please contact us directly.' },
      409
    );
  }

  const { data: inserted, error } = await sb
    .from('order_edit_requests')
    .insert({ order_id: order.id, message })
    .select('id, message, created_at, resolved_at')
    .single();
  if (error) return c.json({ error: error.message }, 500);

  // The message itself is deliberately NOT interpolated into the trail:
  // staff read it in full on the order page, and the trail stays a
  // scannable list of what happened (same rule as the cancellation note).
  await logOrderEvent(sb, order.id, 'Customer requested changes.');
  await recordNotification(sb, {
    kind: 'edit_request',
    orderId: order.id,
    orderNumber: order.order_number,
    customerName: displayName(order.customer),
  });

  return c.json({ data: publicEditRequests([inserted])[0] });
});

/* ------------------------------------------------------------------ */
/* Appointment pages (both kinds; token belongs to the appointment)    */
/* ------------------------------------------------------------------ */

/** Loads an appointment (+customer +order number) by public token. */
async function loadAppointmentByToken(sb: SupabaseClient, token: string) {
  const { data } = await sb
    .from('appointments')
    .select(
      'id, kind, appointment_date, appointment_time, status, ' +
      'customer:customers(first_name, last_name), order:orders(order_number)'
    )
    .eq('public_token', token)
    .maybeSingle();
  return data as Record<string, any> | null;
}

/** Best-effort internal notice when a customer responds to a visit. */
async function notifyAppointmentResponse(
  c: { env: Env },
  appt: Record<string, any>,
  confirmed: boolean,
  note?: string
): Promise<void> {
  try {
    const sb = createSupabaseAdmin(c.env);
    const { data: company } = await sb
      .from('company_settings')
      .select('email, company_name')
      .eq('id', 1)
      .single();
    if (!company?.email) return;
    const customerName = displayName(appt.customer);
    const isInstall = appt.kind === 'installation';
    const label = isInstall
      ? `order ${appt.order?.order_number ?? ''}`.trim()
      : customerName || 'a customer';
    const build = isInstall ? buildInstallationNoticeHtml : buildAppointmentNoticeHtml;
    await sendEmail(c.env, {
      to: company.email,
      subject: confirmed
        ? `✅ ${isInstall ? 'Installation' : 'Estimate appointment'} confirmed — ${label}`
        : `🕑 ${isInstall ? 'Installation' : 'Appointment'} time change requested — ${label}`,
      html: build({
        orderNumber: appt.order?.order_number ?? customerName,
        customerName,
        confirmed,
        note,
      }),
    });
  } catch (e) {
    console.error('Appointment notification failed:', e);
  }
}

/** Public appointment view — everything the AppointmentView page needs. */
app.get('/appointment/:token', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Appointment not found' }, 404);

  const sb = createSupabaseAdmin(c.env);
  const appt = await loadAppointmentByToken(sb, token);
  if (!appt) return c.json({ error: 'Appointment not found' }, 404);

  const { data: company } = await sb
    .from('company_settings')
    .select('company_name, logo_url, email, phone')
    .eq('id', 1)
    .single();

  // Sanitized payload: only what the appointment page needs.
  return c.json({
    data: {
      kind: appt.kind,
      status: appt.status,
      appointment_date: appt.appointment_date,
      appointment_time: appt.appointment_time,
      // Present for installations only — estimates carry no order.
      order_number: appt.order?.order_number ?? null,
      customer_first_name: appt.customer?.first_name ?? '',
      company,
    },
  });
});

/**
 * Customer confirms the proposed visit window (either kind).
 * 404 unknown token · 409 when there is no proposal to confirm.
 */
app.post('/appointment/:token/confirm', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Appointment not found' }, 404);

  const sb = createSupabaseAdmin(c.env);
  const appt = await loadAppointmentByToken(sb, token);
  if (!appt) return c.json({ error: 'Appointment not found' }, 404);
  if (appt.status !== 'proposed') {
    return c.json({ error: 'There is no appointment time to confirm right now.' }, 409);
  }

  const { error } = await sb
    .from('appointments')
    .update({ status: 'confirmed', confirmed_at: new Date().toISOString() })
    .eq('id', appt.id)
    .eq('status', 'proposed');
  if (error) return c.json({ error: error.message }, 500);

  await notifyAppointmentResponse(c, appt, true);
  return c.json({ data: { status: 'confirmed' } });
});

/**
 * Customer requests a different visit time (optional note, both kinds).
 * 404 unknown token · 409 when there is no active proposal.
 */
app.post('/appointment/:token/request', async (c) => {
  const token = c.req.param('token');
  if (!TOKEN_RE.test(token)) return c.json({ error: 'Appointment not found' }, 404);

  const body = (await c.req.json().catch(() => ({}))) as { note?: unknown };
  const note = typeof body.note === 'string' ? body.note.slice(0, 500) : '';

  const sb = createSupabaseAdmin(c.env);
  const appt = await loadAppointmentByToken(sb, token);
  if (!appt) return c.json({ error: 'Appointment not found' }, 404);
  if (!['proposed', 'confirmed'].includes(appt.status)) {
    return c.json({ error: 'There is no appointment time to change right now.' }, 409);
  }

  const { error } = await sb
    .from('appointments')
    .update({ status: 'change_requested', response_note: note })
    .eq('id', appt.id);
  if (error) return c.json({ error: error.message }, 500);

  await notifyAppointmentResponse(c, appt, false, note);
  return c.json({ data: { status: 'change_requested' } });
});

export default app;
